// Asset registry. The SVGs are generated by scripts/build-collectibles.mjs; swapping any of
// them for a pre-rendered WebP/PNG of the same name only requires changing the import here.
import b10 from './b10.svg';
import b20 from './b20.svg';
import b50 from './b50.svg';
import emerald from './emerald.svg';
import g1000 from './g1000.svg';
import g500 from './g500.svg';
import platinum from './platinum.svg';
import s100 from './s100.svg';
import s200 from './s200.svg';
import wild from './wild.svg';
import bolt from './emblem-bolt.svg';
import clover from './emblem-clover.svg';
import flame from './emblem-flame.svg';
import lens from './emblem-lens.svg';
import magnet from './emblem-magnet.svg';
import vault from './emblem-vault.svg';
import type { EmblemName } from '../../config/cards';
import type { CoinId } from '../../game/types';

export const COIN_ART: Record<CoinId, string> = { b10, b20, b50, s100, s200, g500, g1000, wild, emerald, platinum };

export const EMBLEM_ART: Record<EmblemName, string> = { bolt, clover, flame, lens, magnet, vault };

/** Preloads every collectible so reels never flash empty images. */
export function preloadCollectibles(): void {
  for (const src of Object.values(COIN_ART)) {
    const img = new Image();
    img.decoding = 'async';
    img.src = src;
  }
}
